insert into materias (carrera_id, nombre, codigo, semestre)
select c.id, d.nombre, d.codigo, d.semestre
from datos d
join carreras c on c.nombre = d.carrera and c.sede = d.sede
where not exists (select 1 from materias m where m.carrera_id = c.id);
